package installation

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"slices"

	"github.com/holon-sh/cli/pkg/mcpcontract"
	"github.com/holon-sh/cli/pkg/tooling"
	"github.com/holon-sh/cli/pkg/typegen"
	"github.com/tailscale/hujson"
)

// stageRuntimeSlots fills the installed SDKs' generated/ slots from the build snapshot.
// It runs after package installation and before the build.
const stageRuntimeSlots = `#!/bin/sh
# Generated by Holon: replace the installed SDKs' generated/ slots with this build's clients.
set -e
for package in holon-sh holon-ui; do
  if [ -d ".holon-types/$package" ] && [ -d "node_modules/$package" ]; then
    rm -rf "node_modules/$package/generated"
    cp -R ".holon-types/$package/generated" "node_modules/$package/generated"
  fi
done
`

// checkPython runs typegen's Python runner with the checker installed at /opt/holon-check importable,
// so mypy checks the app with the app's own interpreter and dependencies.
const checkPython = `import os
import subprocess
import sys
from pathlib import Path

purelib = subprocess.run(
    ["/opt/holon-check/bin/python", "-c", "import sysconfig; print(sysconfig.get_path('purelib'))"],
    check=True, capture_output=True, text=True,
).stdout.strip()
os.environ["PYTHONPATH"] = os.pathsep.join(filter(None, [purelib, os.environ.get("PYTHONPATH")]))
runner = Path(__file__).parent / "python" / "runner.py"
os.execv(sys.executable, [sys.executable, str(runner), *sys.argv[1:]])
`

// stageTypes writes app's generated clients into its build snapshot and returns the railpack
// configuration that installs and checks them, or "" when it has none. Python and Go clients are
// source files; the TypeScript clients fill the generated/ slots of the holon-sh and holon-ui packages
// that the app's own install fetches.
func stageTypes(p *preparedTypes, check bool) (string, error) {
	targets := p.prepared.Targets(p.name)
	if len(targets) == 0 {
		return "", nil
	}
	directory := filepath.Join(p.root, ".holon-types")
	if err := os.Mkdir(directory, 0o755); err != nil {
		return "", fmt.Errorf("prepare MCP types (.holon-types is reserved): %w", err)
	}
	for _, target := range targets {
		path := p.root
		switch target {
		case typegen.TargetTS:
			path = filepath.Join(directory, nodeRuntime)
		case typegen.TargetUI:
			path = filepath.Join(directory, uiRuntime)
		}
		if err := os.MkdirAll(path, 0o755); err != nil {
			return "", err
		}
		if err := p.prepared.WriteSlot(p.name, target, path); err != nil {
			return "", fmt.Errorf("%s: %w", p.name, err)
		}
	}
	var before, after, install []any
	if slices.Contains(targets, typegen.TargetTS) || slices.Contains(targets, typegen.TargetUI) {
		if err := os.WriteFile(filepath.Join(directory, "stage.sh"), []byte(stageRuntimeSlots), 0o755); err != nil {
			return "", err
		}
		if err := stageNodePackage(p.root); err != nil {
			return "", fmt.Errorf("%s: %w", p.name, err)
		}
		before = append(before, "sh .holon-types/stage.sh")
	}
	if config, ok := p.prepared.CheckConfig(p.name); ok && check {
		if err := tooling.Unpack(directory); err != nil {
			return "", err
		}
		if err := writeTypeJSON(filepath.Join(directory, "check.json"), config); err != nil {
			return "", err
		}
		runner := "node .holon-types/typescript/runner.mjs"
		if slices.Contains(targets, typegen.TargetPy) {
			runner = "python .holon-types/check.py"
			if err := os.WriteFile(filepath.Join(directory, "check.py"), []byte(checkPython), 0o644); err != nil {
				return "", err
			}
			install = checkerInstall
		}
		before = append(before, runner+" check .holon-types/check.json")
		after = append(after, runner+" verify .holon-types/check.json")
	}
	if len(before) == 0 {
		return "", stabilizeTimes(p.root)
	}
	railpack, err := checkedBuild(filepath.Join(p.root, "railpack.json"), before, after, install)
	if err != nil {
		return "", err
	}
	if err := writeTypeJSON(filepath.Join(directory, "railpack.json"), railpack); err != nil {
		return "", err
	}
	return ".holon-types/railpack.json", stabilizeTimes(p.root)
}

// checkerInstall installs the Python type checker ahead of the app's dependency installation
// ("..."), so its layers depend on the base image only and survive source and dependency changes.
// It lives in the builder stage only: the runtime copies /opt/venv and /app.
var checkerInstall = []any{
	"python -m venv /opt/holon-check",
	"/opt/holon-check/bin/pip install --disable-pip-version-check --no-cache-dir mypy==2.4.0",
}

func railpackConfig(path string) (map[string]any, error) {
	data, err := os.ReadFile(path)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	config := map[string]any{}
	if len(bytes.TrimSpace(data)) > 0 {
		if data, err = hujson.Standardize(data); err != nil {
			return nil, fmt.Errorf("railpack.json: %w", err)
		}
		if err := json.Unmarshal(data, &config); err != nil {
			return nil, fmt.Errorf("railpack.json: %w", err)
		}
	}
	return config, nil
}

func checkedBuild(path string, before, after, install []any) (map[string]any, error) {
	config, err := railpackConfig(path)
	if err != nil {
		return nil, err
	}
	surround := func(name string, before, after []any) {
		step := objectField(objectField(config, "steps"), name)
		commands, ok := step["commands"].([]any)
		if !ok {
			commands = []any{"..."}
		}
		step["commands"] = slices.Concat(before, commands, after)
	}
	if len(install) > 0 {
		surround("install", install, nil)
	}
	surround("build", before, after)
	return config, nil
}

// stageNodePackage stages the generated clients before the build copy's own postinstall.
func stageNodePackage(root string) error {
	path := filepath.Join(root, "package.json")
	var pkg map[string]any
	if err := readTypeJSON(path, &pkg); err != nil {
		return err
	}
	scripts := objectField(pkg, "scripts")
	stage := "[ ! -f .holon-types/stage.sh ] || sh .holon-types/stage.sh"
	if existing, _ := scripts["postinstall"].(string); existing != "" {
		stage += " && " + existing
	}
	scripts["postinstall"] = stage
	return writeTypeJSON(path, pkg)
}

// stabilizeTimes gives the files Holon wrote into the snapshot content-derived mtimes, so BuildKit's
// incremental context sync resends only those that changed.
func stabilizeTimes(root string) error {
	for _, directory := range []string{".holon-types", "holon", "package.json"} {
		err := filepath.WalkDir(filepath.Join(root, directory), func(path string, entry fs.DirEntry, err error) error {
			if err != nil || entry.IsDir() {
				return err
			}
			data, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			return os.Chtimes(path, mcpcontract.StableTime(data), mcpcontract.StableTime(data))
		})
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return err
		}
	}
	return nil
}

func objectField(parent map[string]any, name string) map[string]any {
	value, ok := parent[name].(map[string]any)
	if !ok {
		value = map[string]any{}
		parent[name] = value
	}
	return value
}

func readTypeJSON(path string, value any) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, value)
}

func writeTypeJSON(path string, value any) error {
	data, _ := json.MarshalIndent(value, "", "  ")
	return mcpcontract.WriteStable(path, append(data, '\n'), 0o644)
}
